const userInput = {
  "symptom": "Synthetic import rejected because root SKILL.md is absent.",
  "revision": "unverified-example",
  "data_classification": "synthetic"
};
return [{json:userInput}];

const items = $input.all();
if (!Array.isArray(items) || items.length !== 1) throw new Error("Exactly one input required");
const d = items[0].json;
if (!d || typeof d !== "object" || Array.isArray(d)) throw new Error("Object input required");
const serialized = JSON.stringify(d);
if (serialized.length > 262144) throw new Error("Input exceeds character budget");
if (!["public", "synthetic"].includes(d.data_classification)) throw new Error("Only public or synthetic input is supported");
if (/"(?:private_key|mnemonic|seed_phrase|api_key|password|authorization|cookie|access_token|decryption_key)"\s*:/i.test(serialized)
 || /\b(?:sk-[A-Za-z0-9]{16,}|gh[pousr]_[A-Za-z0-9]{20,})\b/.test(serialized)
 || /-----BEGIN [^-]*PRIVATE KEY-----/.test(serialized))
 throw new Error("Possible credential input rejected; use a secret manager");
if (d.approved === true || d.authorized === true) throw new Error("Input booleans do not authorize execution");
if (d.provider_spend_budget !== undefined && d.provider_spend_budget !== 0) throw new Error("Preparation templates support zero added provider spend only");
const envelope = {schema:"hab-preparation/1", mode:"PREPARATION_ONLY", execution_enabled:false,
 provider_calls_enabled:false, financial_actions_enabled:false, provider_spend_budget:0};

function label(v, field, limit=500) {
 if (typeof v!=="string" || !v.trim() || v.length>limit) throw new Error("Invalid "+field);
 return v;
}
function list(v, field, limit=20) {
 if (!Array.isArray(v) || !v.length || v.length>limit) throw new Error("Invalid "+field);
 return [...new Set(v.map(x=>label(x,field,200)))];
}
const extra = JSON.stringify(d);
if (/"(?:private[-_]?key|api[-_]?key|seed[-_]?phrase|access[-_]?token|decryption[-_]?key)"\s*:/i.test(extra))
 throw new Error("Credential field rejected");

const symptom=label(d.symptom,"redacted symptom",2000), revision=label(d.revision,"revision",100);
return [{json:{...envelope,reported_symptom:symptom,reported_revision:revision,
 steps:["Reproduce and record exact inputs/environment","Inspect relevant code, issue history and existing fixes","Separate observations from hypotheses","Run discriminating bounded checks","Propose minimal fix preserving current behavior","Run targeted tests and observe outcome","Record remaining uncertainty and rollback"],
 cause_confirmed:false,fix_applied:false,checks_executed:0}}];
